//! The tampered-input corpus in `tests/corpus/`. Each file is one input a
//! compromised control plane could send to an enforcer, and the refusal code
//! it must get. The files also seed the fuzz target.
//!
//! The fixtures are deterministic, so the files are regenerated byte for
//! byte with `UPDATE_CORPUS=1 cargo test -p alien-signing --test corpus`.

#![allow(clippy::result_large_err)]

mod common;

use std::path::PathBuf;

use alien_signing::envelope::Envelope;
use alien_signing::{ConfigBody, Kind, Ledger, SignedStatement, Trust};
use base64::engine::general_purpose::STANDARD;
use base64::Engine as _;
use chrono::Duration;
use common::*;
use serde::{Deserialize, Serialize};

#[derive(Debug, Serialize, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct Case {
    /// What the attack is.
    description: String,
    /// Refusal code the enforcer must report.
    expect: String,
    /// The statement the control plane sends.
    statement: SignedStatement,
}

fn cases() -> Vec<(&'static str, Case)> {
    let keys = keys();
    let case = |description: &str, expect: &str, statement: SignedStatement| Case {
        description: description.to_string(),
        expect: expect.to_string(),
        statement,
    };

    let good = release(&keys, 20);
    let mut changed_byte = good.clone();
    let mut bytes = good.open().unwrap().bytes;
    let at = bytes
        .windows(4)
        .position(|window| window == b"8080")
        .unwrap();
    bytes[at] = b'9';
    changed_byte.payload = STANDARD.encode(&bytes);

    let config_as_release = statement(
        "config/v1",
        PROJECT,
        Some(INSTALL),
        20,
        1,
        ConfigBody::default(),
    )
    .sign_with("ci", &keys.ci)
    .unwrap();
    let other_project = statement("release/v2", "prj_other", None, 20, 1, release_body())
        .sign_with("ci", &keys.ci)
        .unwrap();
    let outsider = statement("release/v2", PROJECT, None, 20, 1, release_body())
        .sign_with("ci", &keys.outsider)
        .unwrap();
    let unsigned = statement("release/v2", PROJECT, None, 20, 1, release_body());
    let by_removed_role = statement("release/v2", PROJECT, None, 20, 1, release_body())
        .sign_with("bob-laptop", &keys.operator)
        .unwrap();

    let mut extra_field = serde_json::to_value(Envelope {
        kind: "release/v2".to_string(),
        project: PROJECT.to_string(),
        install: None,
        sequence: 20,
        not_after: None,
        signer_list_version: 1,
        body: release_body(),
    })
    .unwrap();
    extra_field["body"]["workloads"][0]["privileged"] = serde_json::json!(true);
    // Keys sorted, so the bytes don't depend on whether the build enables
    // serde_json's preserve_order.
    let extra_bytes = serde_json::to_vec(&sorted(extra_field)).unwrap();
    let extra_field = SignedStatement {
        payload: STANDARD.encode(&extra_bytes),
        signatures: vec![alien_signing::Signature {
            signer: "ci".to_string(),
            sig: keys.ci.sign(&extra_bytes),
        }],
    };

    let expired = SignedStatement::new(
        &Envelope {
            kind: "release/v2".to_string(),
            project: PROJECT.to_string(),
            install: None,
            sequence: 20,
            not_after: Some(now() - Duration::hours(1)),
            signer_list_version: 1,
            body: release_body(),
        }
        .to_payload()
        .unwrap(),
    )
    .sign_with("ci", &keys.ci)
    .unwrap();

    let mut unlinked = version_3_body(&keys);
    unlinked.previous = Some(genesis(&keys).open().unwrap().digest);
    let unlinked = list(PROJECT, 3, 2, unlinked)
        .sign_with("alice-laptop", &keys.admin)
        .unwrap()
        .sign_with("carol-laptop", &keys.second_admin)
        .unwrap();

    let mut fork_body = version_2_body(&keys);
    fork_body.admin_threshold = 1;
    fork_body
        .signers
        .retain(|signer| signer.id != "carol-laptop");
    let fork = list(PROJECT, 2, 1, fork_body)
        .sign_with("alice-laptop", &keys.admin)
        .unwrap();

    let one_admin = list(PROJECT, 3, 2, version_3_body(&keys))
        .sign_with("alice-laptop", &keys.admin)
        .unwrap();

    let mut off_curve = version_3_body(&keys);
    let mut der = STANDARD
        .decode(
            off_curve.signers[0]
                .key
                .strip_prefix("ecdsa-p256:")
                .unwrap(),
        )
        .unwrap();
    let last = der.len() - 1;
    der[last] ^= 0x01;
    off_curve.signers[0].key = format!("ecdsa-p256:{}", STANDARD.encode(&der));
    let off_curve = list(PROJECT, 3, 2, off_curve)
        .sign_with("alice-laptop", &keys.admin)
        .unwrap()
        .sign_with("carol-laptop", &keys.second_admin)
        .unwrap();

    let mut dev_body = release_body();
    dev_body.channel = "dev".to_string();
    let dev_release = statement("release/v2", PROJECT, None, 20, 1, dev_body)
        .sign_with("ci", &keys.ci)
        .unwrap();

    let mut refresh = version_3_body(&keys);
    refresh.previous = Some(version_2(&keys).open().unwrap().digest);
    let refreshed_by_ci = list(PROJECT, 3, 2, refresh)
        .sign_with("ci", &keys.ci)
        .unwrap();

    vec![
        (
            "changed-byte",
            case(
                "a release with one payload byte changed",
                "SIGNING_SIGNATURE_REFUSED",
                changed_byte,
            ),
        ),
        (
            "swapped-kind",
            case(
                "a config statement sent as a release",
                "SIGNING_WRONG_KIND",
                config_as_release,
            ),
        ),
        (
            "other-project",
            case(
                "a release signed for another project",
                "SIGNING_WRONG_PROJECT",
                other_project,
            ),
        ),
        (
            "outsider-key",
            case(
                "a release signed by a key that is not on the list",
                "SIGNING_SIGNATURE_REFUSED",
                outsider,
            ),
        ),
        (
            "unsigned",
            case("a release with no signature", "SIGNING_UNSIGNED", unsigned),
        ),
        (
            "wrong-role",
            case(
                "a release signed by a key without the release role",
                "SIGNING_SIGNATURE_REFUSED",
                by_removed_role,
            ),
        ),
        (
            "unknown-field",
            case(
                "a release that adds a field the enforcer does not know",
                "SIGNING_BODY_REFUSED",
                extra_field,
            ),
        ),
        (
            "expired",
            case("a release past its notAfter", "SIGNING_EXPIRED", expired),
        ),
        (
            "broken-chain-link",
            case(
                "a signer list that skips the version before it",
                "SIGNING_SIGNER_LIST_REFUSED",
                unlinked,
            ),
        ),
        (
            "older-list-fork",
            case(
                "a different version 2 after version 2 is trusted",
                "SIGNING_SIGNER_LIST_REFUSED",
                fork,
            ),
        ),
        (
            "below-threshold",
            case(
                "a signer list signed by fewer admins than required",
                "SIGNING_SIGNER_LIST_REFUSED",
                one_admin,
            ),
        ),
        (
            "dev-release",
            case(
                "a release for the dev channel sent to a production install",
                "SIGNING_WRONG_CHANNEL",
                dev_release,
            ),
        ),
        (
            "refreshed-by-ci",
            case(
                "a signer list refresh signed by CI, which is not an admin",
                "SIGNING_SIGNATURE_REFUSED",
                refreshed_by_ci,
            ),
        ),
        (
            "invalid-curve-point",
            case(
                "a signer list holding a key that is not on the curve",
                "SIGNING_SIGNER_LIST_REFUSED",
                off_curve,
            ),
        ),
    ]
}

/// What an enforcer at signer list version 2 reports.
fn run(case: &Case) -> String {
    let keys = keys();
    let ledger = Ledger::new(PREFIX);
    let mut trust = Trust::new(
        settings(&keys),
        install(),
        &[genesis(&keys), version_2(&keys)],
        &ledger,
        now(),
    )
    .unwrap();
    let opened = match case.statement.open() {
        Ok(opened) => opened,
        Err(error) => return error.code,
    };
    let result = if opened.kind == Kind::SignerList {
        trust
            .extend_chain(std::slice::from_ref(&case.statement), now())
            .map(|_| ())
    } else {
        trust.verify_release(&case.statement, now()).map(|_| ())
    };
    match result {
        Ok(()) => "ACCEPTED".to_string(),
        Err(error) => error.code,
    }
}

fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/corpus")
}

#[test]
fn every_tampered_input_is_refused_with_its_reason() {
    let update = std::env::var_os("UPDATE_CORPUS").is_some();
    let dir = corpus_dir();
    if update {
        std::fs::create_dir_all(&dir).unwrap();
    }
    for (name, case) in cases() {
        let path = dir.join(format!("{name}.json"));
        let text = serde_json::to_string_pretty(&case).unwrap() + "\n";
        if update {
            std::fs::write(&path, &text).unwrap();
        }
        let stored: Case = serde_json::from_slice(&std::fs::read(&path).unwrap_or_else(|error| {
            panic!("{}: {error}; run with UPDATE_CORPUS=1", path.display())
        }))
        .unwrap();
        assert_eq!(
            stored, case,
            "{name}: the stored case is stale; run with UPDATE_CORPUS=1"
        );
        assert_eq!(
            run(&stored),
            stored.expect,
            "{name}: {}",
            stored.description
        );
    }
}

#[test]
fn the_untampered_inputs_are_accepted() {
    let keys = keys();
    let ok = Case {
        description: "a newer release".to_string(),
        expect: "ACCEPTED".to_string(),
        statement: release(&keys, 11),
    };
    assert_eq!(run(&ok), "ACCEPTED");
    let next = Case {
        description: "version 3 signed by both admins".to_string(),
        expect: "ACCEPTED".to_string(),
        statement: version_3(&keys),
    };
    assert_eq!(run(&next), "ACCEPTED");
}

fn sorted(value: serde_json::Value) -> serde_json::Value {
    match value {
        serde_json::Value::Object(map) => {
            let keys: std::collections::BTreeMap<String, serde_json::Value> =
                map.into_iter().collect();
            serde_json::Value::Object(keys.into_iter().map(|(k, v)| (k, sorted(v))).collect())
        }
        serde_json::Value::Array(items) => {
            serde_json::Value::Array(items.into_iter().map(sorted).collect())
        }
        other => other,
    }
}
